  "message": "Extracting each tool's full verbatim subtitle for the overview cards",
  "input": {
    "command": "cd /home/claude/Working-main/Amazon_Tools && python3 << 'EOF'
import re, html, json
dirs = ["market_diligence_scorecard","launch_control_console","mature_asset_console","forecast_workbench","keyword_structure_lab","keywordsgroup","advertising","ad_logic_lab","Amazon_PPC_Deep_Structure_Atlas","computational_advertising_atlas"]
out = {}
for d in dirs:
    s = open(f"{d}/index.html", encoding="utf-8").read()
    body = re.sub(r'<script.*?</script>','',s,flags=re.S)
    body = re.sub(r'<style.*?</style>','',body,flags=re.S)
    h1 = re.search(r'<h1[^>]*>(.*?)</h1>', body, re.S)
    sub_txt = ""
    if h1:
        after = body[h1.end():h1.end()+2500]
        sub = re.search(r'<(p|div)[^>]*>(.*?)</\1>', after, re.S)
        if sub:
            sub_txt = re.sub(r'\s+',' ', re.sub(r'<[^>]+>','', html.unescape(sub.group(2)))).strip()
    else:
        # computational atlas: p.sub
        m = re.search(r'class="sub"[^>]*>(.*?)</p>', body, re.S)
        if m: sub_txt = re.sub(r'\s+',' ', re.sub(r'<[^>]+>','', html.unescape(m.group(1)))).strip()
    out[d] = sub_txt
print(json.dumps(out, ensure_ascii=False, indent=1))
EOF",
    "description": "Extracting each tool's full verbatim subtitle for the overview cards"
  },
