    src = open(path, encoding='utf-8').read()
    # 检查未转义的 & (不属于 &amp; 等实体)
    for m in re.finditer(r'&(?!amp;|lt;|gt;|quot;|#)', src):
        errors.append(f'{path}: 未转义 & at {m.start()}')
    stack = []
    for m in re.finditer(r'<(/?)([a-zA-Z][a-zA-Z0-9-]*)((?:"[^"]*"|\'[^\']*\'|[^>"\'])*)(/?)>', src):
