  '法则条数': html.count('<span class="rnum">'),
  '术语条数': html.count('<div class="term">'),
  'case 例证': html.count('class="case"') - html.count('case-tag'),
}
# 标签配平
for tag in ['section','main','div','table','tr','td','th','ol','li','p','h2','h3','figure','nav','header','footer','script','a','span','b','strong','em','i']:
    opens = len(re.findall(r'<%s(\s|>)' % tag, html))
    closes = html.count('</%s>' % tag)
    if opens != closes:
        print('不配平: <%s> open=%d close=%d' % (tag, opens, closes))
print('检查:', checks)
# 锚点齐备
for aid in ['chain','p1','p2','p3','p4','p5','p6','p7','p8','p9','p10','p11','axioms','rules','glossary']:
    if ('id="%s"' % aid) not in html:
        print('缺锚点:', aid)
print('锚点检查完成; 总字节', len(html.encode('utf-8')))
