 const u=DB.users.find(x=>x.phone===acc&&x.pwd===pw);if(!u)return toast('账号或密码不正确','err');if(u.status==='禁用')return toast('账号已被禁用,请联系管理员','err');
 setSes({role:'user',uid:u.id});toast('欢迎回来,'+u.wechat);go('home')},
reg(){const p=$('#rphone').value.trim(),c=$('#rcode').value.trim(),w=$('#rpwd').value,wx=$('#rwx').value.trim(),al=$('#rali').value.trim(),an=$('#raln').value.trim();
 if(!/^1\d{10}$/.test(p))return toast('手机号格式不正确','err');
 if(DB.users.some(u=>u.phone===p))return toast('该手机号已注册,请直接登录','err');
 if(c!=='123456')return toast('验证码不正确(演示码 123456)','err');
 if(w.length<6)return toast('密码至少 6 位','err');
 if(!wx)return toast('请填写微信号','err');
 if(DB.users.some(u=>u.wechat===wx))toast('提示:该微信号已被绑定过,提交后将由管理员人工核实');
 if(!al||!an)return toast('请填写支付宝账号与实名姓名','err');
