 const u={id:uid(),phone:p,pwd:w,wechat:wx,alipayAcc:al,alipayName:an,status:'正常',createdAt:now()};DB.users.push(u);oplog('系统','用户注册',wx);save();setSes({role:'user',uid:u.id});toast('注册成功');go('home')},
