        dx,dy=bx-ax,by-ay
        if dx==dy==0: return (px-ax)**2+(py-ay)**2
        t=((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)
        t=max(0,min(1,t))
        qx,qy=ax+t*dx,ay+t*dy
