/* ======================== M5 TACOS 飞轮 ======================== */
function parseTacos(){
  const lines=$('ta_tacos').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);
  const out=[];
  lines.forEach(l=>{
    const p=l.split(/[,，\t]+/).map(x=>x.trim());
    if(p.length<4) return;
    const total=num(p[1]), adSales=num(p[2]), adSpend=num(p[3]);
    if(total<=0) return;
    out.push({period:p[0], total, adSales, adSpend, tacos:adSpend/total, acos:adSales>0?adSpend/adSales:null, organic:1-adSales/total});
  });
  S.tacos=out;
  renderM5();
}
function renderM5(){
  const D=S.tacos;
  if(!D.length){ $('m5body').innerHTML=''; return; }
  let h='<div class="chartbox" style="height:340px"><canvas id="c_tacos"></canvas></div>';
  const tr=D.map(d=>[d.period,money(d.total),money(d.adSales),money(d.adSpend),fp(d.tacos,1),fp(d.acos,1),fp(d.organic,1)]);
  h+=tbl(['期间','总销售额','广告销售额','广告花费','TACOS','ACOS','自然占比'],tr,[1,2,3,4,5,6]);
  $('m5body').innerHTML=h;
  /* 徽章 */
  let bh='';
  if(D.length>=4){
    const sT=slope(D.map(d=>d.tacos*100)), sA=slope(D.map(d=>(d.acos||0)*100)), sO=slope(D.map(d=>d.organic*100));
    const fly = sT<-0.15 && sA>-0.08;
    const dep = !fly && D.reduce((s,d)=>s+d.organic,0)/D.length<0.4 && sO<=0.05;
    bh+='<div style="margin-bottom:8px">'+
      '<span class="badge '+(fly?'on':'na')+'">飞轮 '+(fly?'启动':'未确认')+'</span>'+
      '<span class="badge '+(dep?'off':'na')+'">广告依赖 '+(dep?'偏高':'可控')+'</span></div>';
    bh+='<p class="small">TACOS 斜率 '+sT.toFixed(2)+' pp/期 · ACOS 斜率 '+sA.toFixed(2)+' pp/期 · 自然占比斜率 '+(sO>=0?'+':'')+sO.toFixed(2)+' pp/期。'+
      (fly?'广告花费效率（ACOS）没变，但占总盘子的比重在降——差额就是广告沉淀出的自然排名资产。此时敢于维持甚至加投。'
          :'尚未出现「TACOS 降、ACOS 平」的剪刀差；若两线长期同步高位横盘，说明停投即停售，利润被广告结构性征税。')+'</p>';
  } else bh='<div class="locked-wait">已录入 '+D.length+' 期，满 4 期后给出斜率判读</div>';
