function readFileToRows(file, cb){
  const ext=file.name.split('.').pop().toLowerCase();
  if(ext==='csv'||ext==='txt'){
    Papa.parse(file,{header:true,skipEmptyLines:true,complete:r=>cb(r.data, r.meta.fields||[])});
  }else{
    const rd=new FileReader();
    rd.onload=e=>{
      const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'});
      const ws=wb.Sheets[wb.SheetNames[0]];
      const aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});
      if(!aoa.length){cb([],[]);return;}
      const headers=aoa[0].map(x=>String(x));
      const rows=aoa.slice(1).filter(r=>r.some(c=>c!=='')).map(r=>{const o={};headers.forEach((h,i)=>o[h]=r[i]);return o;});
      cb(rows, headers);
    };
    rd.readAsArrayBuffer(file);
  }
}
function autoMap(headers, spec){
  const nh=headers.map(h=>({raw:h, n:normH(h)}));
  const map={}, missing=[];
  Object.keys(spec).forEach(k=>{
    const f=spec[k]; let found=null;
    for(const c of f.cands){ const cn=normH(c); const ex=nh.find(x=>x.n===cn); if(ex){found=ex.raw;break;} }
    if(!found){ for(const c of f.cands){ const cn=normH(c);
      const inc=nh.find(x=>x.n.includes(cn) && !(f.excl||[]).some(e=>x.n.includes(normH(e))));
      if(inc){found=inc.raw;break;} } }
    if(found) map[k]=found; else if(!f.optional) missing.push(k);
  });
  return {map, missing};
}
