/* ======================== 纯函数（可测） ======================== */
function num(v){ if(v==null) return 0; const s=String(v).replace(/[^0-9.\-]/g,''); const f=parseFloat(s); return isFinite(f)?f:0; }
function pct(v){ const f=num(v); return f>1.5? f/100 : f; }
function avg(a){ return a.length? a.reduce((x,y)=>x+y,0)/a.length : 0; }
function clamp(v,lo,hi){ return Math.max(lo,Math.min(hi,v)); }
function slope(ys){ const n=ys.length; if(n<2) return 0;
  const xm=(n-1)/2, ym=avg(ys);
  let nu=0,de=0; for(let i=0;i<n;i++){nu+=(i-xm)*(ys[i]-ym);de+=(i-xm)*(i-xm);}
  return de? nu/de:0;
}
/* 参数派生：判决书 → 作战阈值 */
function deriveParams(P){
  const cpcMid=(P.cpcLo+P.cpcHi)/2;
  const beCVR=P.cm>0? cpcMid/P.cm : null;              // 平衡 CVR（广告不亏下限）
  const beACOS=(P.price>0&&P.cm>0)? P.cm/P.price : null; // 平衡 ACOS
  const g2CVR=beCVR!=null? beCVR*0.85 : null;           // G2 生死线（评论未到稳态打八五折）
  const infoCap=P.kws*P.clicksKw*cpcMid;
  const organicNeed=Math.max(0,P.p25-P.vine);
  const ordersNeed=P.reviewRate>0? Math.ceil(organicNeed/P.reviewRate) : 0;
  const reviewCap=ordersNeed*P.subsidy;
  return {cpcMid,beCVR,beACOS,g2CVR,infoCap,organicNeed,ordersNeed,reviewCap};
}
