/* 三本账燃烧 */
function computeBurns(rows,D,P){
  let info=0,review=0,rank=0;
  const series=rows.map(r=>{
    if(r.wk<=8) info+=r.adSpend;
    if(r.wk<=P.subWeeks) review+=r.units*P.subsidy;
