const sharp = require("sharp");
const fs = require("fs");

// Build a clean Greek-key (meander) band as a continuous single stroke that tiles horizontally.
// Unit cell is a spiral hook; cells connect along a baseline. Verified geometry.
function meanderSVG({tiles=12, u=16, stroke=4, color="#C8A24A", h=null}){
  // one cell is 6u wide, 6u tall. Continuous line per cell:
  // baseline at y=5u; spiral up-right-down-left-in.
  const cellW = 6*u;
  const H = h || 6*u + stroke;
  const W = tiles*cellW + stroke;
  let d = "";
  for(let i=0;i<tiles;i++){
    const x = i*cellW + stroke/2;
    const y0 = stroke/2;
    // points relative, y down. Spiral key:
    const pts = [
      [0,5],[0,1],[4,1],[4,4],[2,4],[2,2],[3,2],[3,3]
    ].map(([px,py])=>[x+px*u, y0+py*u]);
    // connector from previous cell baseline into this cell start handled by baseline run:
    d += `M ${x - (i>0?0:0)} ${y0+5*u} L ${pts[0][0]} ${pts[0][1]} `;
    d += "L " + pts.slice(1).map(p=>p.join(" ")).join(" L ") + " ";
    // baseline run to next cell
    d += `M ${pts[0][0]} ${y0+5*u} L ${x+6*u} ${y0+5*u} `;
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <path d="${d}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="square" stroke-linejoin="miter"/>
  </svg>`;
}

async function main(){
  const svg = meanderSVG({tiles:20, u:18, stroke:5, color:"#C8A24A"});
  fs.writeFileSync("meander_preview.svg", svg);
  await sharp(Buffer.from(svg)).png().toFile("meander_preview.png");
  console.log("done");
}
main();
