{
  "message": "Deck-viewer Mini Program logic (index.js)",
  "input": {
    "description": "Deck-viewer Mini Program logic (index.js)",
    "file_text": "// 古希腊哲学·操作系统 —— 讲义放映小程序
function pad(n){ return n < 10 ? '0' + n : '' + n; }

const RAW = [
  { kind:'序', title:'整个古希腊哲学的操作系统', sub:'PROLOGOS · 序章', chip:'序章' },
  { kind:'图', title:'十六组核心二元对立', sub:'THE CONSTELLATION · 星座图', chip:'星座图' },
  { kind:'幕', title:'起点：哲学是怎么诞生的', sub:'PHASE Ⅰ', chip:'Ⅰ 起点' },
  { kind:'01', title:'神话 — 理性', sub:'Μῦθος · Λόγος' },
  { kind:'02', title:'自然 — 约定', sub:'Φύσις · Νόμος' },
  { kind:'幕', title:'宇宙论：找“那个东西”', sub:'PHASE Ⅱ', chip:'Ⅱ 宇宙论' },
  { kind:'03', title:'无定 — 有限', sub:'Ἄπειρον · Πέρας' },
  { kind:'04', title:'一 — 多', sub:'Ἕν · Πολλά' },
  { kind:'幕', title:'巴门尼德冲击：哲学进入存在论主场', sub:'PHASE Ⅲ', chip:'Ⅲ 巴门尼德' },
  { kind:'05', title:'真理 — 意见', sub:'Ἐπιστήμη · Δόξα' },
  { kind:'06', title:'思维 — 存在', sub:'Νοεῖν · Εἶναι' },
  { kind:'07', title:'存在 — 非存在', sub:'Ὄν · Μὴ Ὄν' },
  { kind:'幕', title:'形而上学的搭建：柏拉图与亚里士多德', sub:'PHASE Ⅳ', chip:'Ⅳ 形而上学' },
  { kind:'08', title:'形式 — 质料', sub:'Μορφή · Ὕλη' },
  { kind:'09', title:'潜能 — 现实', sub:'Δύναμις · Ἐνέργεια' },
  { kind:'10', title:'个别 — 共相', sub:"Καθ' ἕκαστον · Καθόλου" },
  { kind:'11', title:'感性 — 理性', sub:'Αἴσθησις · Νοῦς' },
  { kind:'12', title:'现象 — 本体', sub:'Φαινόμενον · Οὐσία' },
  { kind:'幕', title:'希腊化转向：从“世界是什么”到“我该如何活”', sub:'PHASE Ⅴ', chip:'Ⅴ 希腊化' },
  { kind:'13', title:'必然 — 自由', sub:'Ἀνάγκη · Προαίρεσις' },
  { kind:'14', title:'德性 — 快乐', sub:'Ἀρετή · Ἡδονή' },
  { kind:'15', title:'灵魂 — 肉体', sub:'Ψυχή · Σῶμα' },
  { kind:'16', title:'悬置判断 — 不动心', sub:'Ἐποχή · Ἀταραξία' },
  { kind:'结', title:'这16对对立到底揭示了什么？', sub:'SYNTHESIS · 结语', chip:'结语' },
  { kind:'尾', title:'尾声', sub:'ΕΠΙΛΟΓΟΣ · 尾声', chip:'尾声' }
];

Page({
  data: {
    slides: [], opps: [], chips: [],
    current: 0, swiperH: 220, cur: {},
    showCat: false, zoom: false, zoomSrc: ''
  },

  onLoad(){
    let W = 375; try { W = (wx.getSystemInfoSync().windowWidth || 375); } catch(e){}
    const slides = RAW.map((s, idx) => ({ i: idx, no: idx + 1, kind: s.kind, title: s.title, sub: s.sub, chip: s.chip || '', src: '/images/slide-' + pad(idx + 1) + '.jpg' }));
    const opps = slides.filter(s => /^\d\d$/.test(s.kind)).map(s => ({ i: s.i, no: s.kind, cn: s.title, gk: s.sub }));
    const chips = slides.filter(s => s.chip).map(s => ({ i: s.i, label: s.chip }));
    this.setData({ slides, opps, chips, swiperH: Math.round(W * 9 / 16), cur: slides[0] });
  },

  onSwiper(e){ const i = e.detail.current; this.setData({ current: i, cur: this.data.slides[i] }); },
  prev(){ if(this.data.current > 0){ const i = this.data.current - 1; this.setData({ current: i, cur: this.data.slides[i] }); } },
