function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 360, after: 200 },
    indent: { firstLine: 480 },
    children: [
      new TextRun({ text, font: FONT_BODY, size: 24, ...opts }),
