  });
}

// parse simple markdown-like emphasis **bold** into runs
function parseRuns(text, baseOpts = {}) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g).filter(p => p.length > 0);
  return parts.map(p => {
    if (p.startsWith("**") && p.endsWith("**")) {
      return new TextRun({ text: p.slice(2, -2), font: FONT_BODY, size: 24, bold: true, ...baseOpts });
    }
    return new TextRun({ text: p, font: FONT_BODY, size: 24, ...baseOpts });
  });
}

function bodyRich(text) {
  return new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 360, after: 200 },
    indent: { firstLine: 480 },
    children: parseRuns(text),
  });
}

