found={k:0 for k in key}
for i,s in enumerate(p.slides,1):
    txt=' '.join(sh.text for sh in s.shapes if sh.has_text_frame)
    # table text
    for sh in s.shapes:
        if sh.has_table:
            for r in sh.table.rows:
                for c in r.cells: txt+=' '+c.text
    for k in key:
        if k in txt: found[k]+=1
    # first line as title
    firstline = next((sh.text.split(chr(10))[0] for sh in s.shapes if sh.has_text_frame and sh.text.strip()), '')
    print(i, firstline[:34])
print('KEYCHECK', found)
" 2>&1 | head -40",
